set ResolutionFormula {                      (abs(eta) <= 1.7) * sqrt(energy^2*0.055^2 + energy*0.564^2 + 1.59^2) +
                             (abs(eta) > 1.7 && abs(eta) <= 3.2) * sqrt(energy^2*0.0^2 + energy*0.762^2) +
                             (abs(eta) > 3.2 && abs(eta) <= 4.9) * sqrt(energy^2*0.035^2 + energy*0.285^2)}

# ATLAS Run-2 MV2c10 70% single-cut OP (arXiv:1907.05120, Table 4 + Fig 8a), |eta|<2.5
# Inclusive (ttbar-averaged): eff_b=0.70, 1/eps_c=8.9, 1/eps_l=300, 1/eps_tau=36.
# pT-dependent turn-on shapes anchored so the ttbar-weighted average reproduces the Table 4 OP values;
# b-eff peaks ~0.78 at 100-150 GeV (Fig 8a) and falls at low/high pT.
module BTagging BTagging {
  set JetInputArray JetEnergyScale/jets
  set BitNumber 0
  # light-flavour (u,d,s,g) mistag: eps_l ~ 1/300 inclusive, rises ~linearly with pT (1/eps_l ~460@20GeV -> ~160@600GeV)
  add EfficiencyFormula {0} {(abs(eta)<2.5)*(0.002+7.3e-06*pt)}
  # c-jet mistag: eps_c ~ 1/8.9 inclusive (turn-on then fall)
  add EfficiencyFormula {4} {(abs(eta)<2.5)*(0.20*tanh(0.02*pt)*(1.0/(1+0.0034*pt)))}
  # b-jet efficiency: 70% OP, turn-on peaking ~0.78 at 100-150 GeV (Fig 8a)
  add EfficiencyFormula {5} {(abs(eta)<2.5)*(0.80*tanh(0.003*pt)*(30.0/(1+0.086*pt)))}
}

## ATLAS TauTagging -- RNN Medium working point (ATL-PHYS-PUB-2019-033, 13 TeV)
## BitNumber 0; codes: 1=1-prong eff, 2=multi(3)-prong eff, -1=1-prong mistag, -2=multi-prong mistag
## Efficiencies flattened ~constant in pT (above ~50 GeV turn-on) and |eta|<2.5 (Fig.6, Table 2).
## Mistag rejection rises strongly with pT (Fig.7): encode pT-binned mistag.

# 1-prong true-tau efficiency (Medium, Table 2)
add EfficiencyFormula {1} {0.75}

# multi-prong (3-prong) true-tau efficiency (Medium, Table 2)
add EfficiencyFormula {2} {0.60}

# 1-prong jet -> tau mistag, pT-binned from Fig.7a (RNN Medium); 1/rejection
add EfficiencyFormula {-1} {
  (pt <= 50.0)  * 0.033  +
  (pt > 50.0  && pt <= 100.0) * 0.0286 +
  (pt > 100.0)                * 0.0091
}

# multi-prong (3-prong) jet -> tau mistag, pT-binned from Fig.7b (RNN Medium); 1/rejection
add EfficiencyFormula {-2} {
  (pt <= 50.0)  * 0.0050  +
  (pt > 50.0  && pt <= 100.0) * 0.0042 +
  (pt > 100.0)                * 0.0006
}
